INSERT INTO `cartas` (`categoria_id`, `qid`, `resposta`, `resposta_normalizada`, `url_fonte`, `resumo_fonte`, `status`) SELECT `id`, 'Q179021', 'O Alquimista', 'o alquimista', 'https://pt.wikipedia.org/wiki/O_Alquimista', 'O Alquimista é um best-seller do escritor brasileiro Paulo Coelho, publicado originalmente em 1988, em português.\nRomance alegórico, O Alquimista segue um jovem pastor andaluz em sua viagem ao Egito, depois de ter um sonho recorrente de encontrar tesouro lá.\nÉ o livro brasileiro mais traduzido do mundo, totalizando 88 idiomas.\nAté 2009, já havia vendido mais de 85 milhões de cópias, tornando-se um dos livros mais vendidos da história.', 'aprovada' FROM `categorias` WHERE `chave` = 'coisa';
