INSERT INTO `cartas` (`categoria_id`, `qid`, `resposta`, `resposta_normalizada`, `url_fonte`, `resumo_fonte`, `status`) SELECT `id`, 'Q22890', 'Irlanda', 'irlanda', 'https://pt.wikipedia.org/wiki/Irlanda_(ilha)', 'A Ilha da Irlanda é a terceira maior ilha da Europa e a vigésima maior do mundo. Encontra-se a noroeste da Europa continental e está cercada por centenas de ilhas e ilhéus. A leste da Irlanda localiza-se a Grã-Bretanha, separada dela pelo Mar da Irlanda. A ilha está dividida entre a República da Irlanda, que cobre um pouco menos do que cinco sextos da ilha, e a Irlanda do Norte, região sob a soberania do Reino Unido, que abrange o restante e está localizada no nordeste da ilha. Pouco menos de 5,1 milhões vivem na República da Irlanda e cerca de 1,9 milhões vivem na Irlanda do Norte. Em 2022, a população foi estimada em mais de 7 milhões de pessoas.', 'aprovada' FROM `categorias` WHERE `chave` = 'lugar';
