INSERT INTO `cartas` (`categoria_id`, `qid`, `resposta`, `resposta_normalizada`, `url_fonte`, `resumo_fonte`, `status`) SELECT `id`, 'Q36755', 'Sinai', 'sinai', 'https://pt.wikipedia.org/wiki/Sinai', 'O Sinai é uma península montanhosa e desértica do Egito, situada na Ásia, entre os golfos de Suez e Ácaba. O nome tem origem no deus Sin, deus da lua. Por isso se diz que Sinai é a \"Terra da Lua\"; e a terra das águas turquesa da Paz. Ocupa uma posição estratégica que une dois continentes - África e Ásia - separando também dois mares - o Mediterrâneo e o Mar Vermelho. A Península tem uma superfície de 61 000 km² em forma triangular dividindo-se em duas partes: Sinai do Norte e do Sul. A sua fauna é muito variada e extremamente rica especialmente em aves. Também a flora é de grande valor, possuindo mais de 5 mil classes de plantas diferentes.', 'aprovada' FROM `categorias` WHERE `chave` = 'lugar';
