INSERT INTO `cartas` (`categoria_id`, `qid`, `resposta`, `resposta_normalizada`, `url_fonte`, `resumo_fonte`, `status`) SELECT `id`, 'Q15031', 'Xi Jinping', 'xi jinping', 'https://pt.wikipedia.org/wiki/Xi_Jinping', 'Xi Jinping é um político chinês. Desde 2013 é o secretário-geral do Partido Comunista da China (PCCh), presidente da Comissão Militar Central (CMC) desde 2012 e presidente da República Popular da China (RPC). Xi tem sido, desde 2012, o líder político mais proeminente da China. Em outubro de 2022, Xi foi reeleito para um terceiro mandato como secretário-geral do PCCh, algo que não acontecia desde a morte de Mao Tsé-Tung.', 'aprovada' FROM `categorias` WHERE `chave` = 'pessoa';
